//! Running a conformance lab for real: generated by this checkout's `isoloom` for a target, then
//! `isothrum up`, `check --json` and `down` (always, unless kept), its check events read back.
//! Each run has its own name and the runner's home under the work folder, so nothing else's runs
//! are touched.

use std::path::{Path, PathBuf};
use std::process::Command;

use isoloom_catalogue::conformance::{ConformanceLab, Form, Run};
use serde_json::Value;

use crate::{Res, process, repo};

/// What runs a lab: the two CLIs, the work folder, the VM form's provider.
pub(crate) struct Runner {
    pub isoloom: PathBuf,
    pub isothrum: PathBuf,
    pub work: PathBuf,
    pub provider: String,
    pub keep: bool,
}

/// This checkout's `isoloom`, built.
pub(crate) fn isoloom(root: &Path) -> Res<PathBuf> {
    process::run(process::cargo(root).args(["build", "-q", "-p", "isoloom"]))?;
    let exe = if cfg!(windows) { "isoloom.exe" } else { "isoloom" };
    Ok(repo::target_dir(root).join("debug").join(exe))
}

/// `lab` written into `dir` (afresh): its spec and its project files.
pub(crate) fn write_lab(dir: &Path, lab: &ConformanceLab) -> Res<()> {
    if dir.exists() {
        repo::remove(dir)?;
    }
    std::fs::create_dir_all(dir)?;
    std::fs::write(dir.join("isoloom.yml"), &lab.spec)?;
    for (path, content) in &lab.project {
        let file = dir.join(path);
        if let Some(parent) = file.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(file, content)?;
    }
    Ok(())
}

/// One run of a lab: its folder, its target, its name and its form.
struct LabRun<'a> {
    dir: &'a Path,
    target: &'static str,
    name: String,
    form: Form,
}

impl Runner {
    /// The lab in `dir` run in `form`: generated, up, checked, down.
    pub(crate) fn run(&self, dir: &Path, form: Form) -> Res<Run> {
        let target = match form {
            Form::Vm => "vagrant",
            _ => "docker",
        };
        process::run(Command::new(&self.isoloom).args(["generate", "--target", target]).arg(dir))?;
        let name = format!("{}-{target}", dir.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default());
        let lab = LabRun { dir, target, name, form };
        let up = self.isothrum("up", &lab).arg("--replace").status();
        let checked = match up {
            Ok(s) if s.success() => self.check(&lab),
            Ok(s) => Err(format!("`isothrum up` failed ({s}) for {} on {target}", dir.display()).into()),
            Err(e) => Err(format!("`{}` couldn't start: {e}", self.isothrum.display()).into()),
        };
        if !self.keep && !self.isothrum("down", &lab).status().is_ok_and(|s| s.success()) {
            eprintln!(
                "catalogue check: `isothrum down` failed for {}: remove it with `{} down {} --target {target} --name {} --home {}`",
                lab.name,
                self.isothrum.display(),
                dir.display(),
                lab.name,
                self.home().display()
            );
        }
        checked
    }

    /// The lab's checks, as the runner reports them.
    fn check(&self, lab: &LabRun<'_>) -> Res<Run> {
        let out = self
            .isothrum("check", lab)
            .arg("--json")
            .output()
            .map_err(|e| format!("`isothrum check` couldn't start: {e}"))?;
        Ok(read_events(&String::from_utf8_lossy(&out.stdout)))
    }

    /// `isothrum <op>` on `lab`, in the work folder's home.
    fn isothrum(&self, op: &str, lab: &LabRun<'_>) -> Command {
        let mut cmd = Command::new(&self.isothrum);
        process::without_run_env(&mut cmd);
        cmd.arg(op)
            .arg(lab.dir)
            .args(["--target", lab.target, "--name", &lab.name, "--home"])
            .arg(self.home());
        if lab.form == Form::Vm && op != "check" {
            cmd.args(["--provider", &self.provider]);
        }
        cmd
    }

    /// The runner's home for these runs.
    fn home(&self) -> PathBuf {
        self.work.join("isothrum-home")
    }
}

/// The check events of an `isothrum check --json` stream: each check's name, whether it passed,
/// and why not.
pub(crate) fn read_events(stream: &str) -> Run {
    let checks = stream
        .lines()
        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
        .filter(|e| e.get("event").and_then(Value::as_str) == Some("check"))
        .map(|e| {
            let text = |k: &str| e.get(k).and_then(Value::as_str).unwrap_or_default().to_owned();
            (text("name"), e.get("ok").and_then(Value::as_bool).unwrap_or(false), text("detail"))
        })
        .collect();
    Run { checks }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_check_events_are_read_with_their_outcome() {
        let stream = concat!(
            r#"{"v":0,"seq":1,"event":"step","step":"checks","state":"running"}"#,
            "\n",
            r#"{"v":0,"seq":2,"event":"check","runner":"r","from":"probe","name":"the port answers","ok":true,"detail":""}"#,
            "\n",
            r#"{"v":0,"seq":3,"event":"check","runner":"r","from":"web","name":"fact: the OS","ok":false,"detail":"debian 12 "}"#,
            "\n",
            "not json\n",
        );
        let run = read_events(stream);
        assert_eq!(
            run.checks,
            [
                ("the port answers".to_owned(), true, String::new()),
                ("fact: the OS".to_owned(), false, "debian 12 ".to_owned())
            ]
        );
    }
}
